{
  "name": "@agent-a/cli",
  "version": "0.1.17",
  "description": "Install and configure your Agent-A AI founding team in OpenCode",
  "main": "bin/agent-a.js",
  "bin": {
    "agent-a": "bin/agent-a.js"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/amonter/agent-a.git",
    "directory": "packages/agent-a-cli"
  },
  "files": [
    "bin/",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "ai",
    "opencode",
    "agent-a",
    "cli",
    "ai-team",
    "founding-team"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=14"
  },
  "dependencies": {
    "chalk": "^4.1.2"
  }
}

#!/usr/bin/env node

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const readline = require('readline');
const { execFileSync, execSync } = require('child_process');

// ── Config paths ────────────────────────────────────────────
const OPENCODE_DIR = path.join(os.homedir(), '.config', 'opencode');
const OPENCODE_CONFIG = path.join(OPENCODE_DIR, 'opencode.json');
const OPENCODE_CONFIGC = path.join(OPENCODE_DIR, 'opencode.jsonc');
const AGENT_A_API_URL = 'https://api.agenta.chat';

const ROLE_ICONS = {
  'strategic-challenger': '\u25A0',       // ■
  'frontend-designer': '\u25B6',  // ▶
  'backend-hacker': '\u25C6',     // ◆
  'backend-hacker-glm': '\u25C7',  // ◇
  'market-operator': '\u25CF',    // ●
};

const ROLE_LABELS = {
  'strategic-challenger': 'Strategic Challenger',
  'frontend-designer': 'Frontend Designer',
  'backend-hacker': 'Backend Hacker',
  'backend-hacker-glm': 'Backend Hacker GLM',
  'market-operator': 'Market Operator',
};

const MODEL_NAMES = {
  'strategic-challenger': 'Strategic Challenger \u00B7 Luna',
  'frontend-designer': 'Frontend Designer \u00B7 Luna',
  'backend-hacker': 'Backend Hacker \u00B7 Gemini 3.7 Flash',
  'backend-hacker-glm': 'Backend Hacker \u00B7 GLM 5.3 Flash',
  'market-operator': 'Market Operator \u00B7 DeepSeek V4',
};

// ── Colors (chalk v4 CJS) ──────────────────────────────────
let chalk;
try {
  chalk = require('chalk');
} catch {
  // Fallback if chalk not installed
  chalk = new Proxy({}, {
    get: () => new Proxy({}, {
      get: () => (s) => s,
    }),
  });
}

// ── Helpers ─────────────────────────────────────────────────
function prompt(question) {
  // Cross-platform: /dev/tty on Unix, process.stdin on Windows
  const isWindows = process.platform === 'win32';
  let inputStream;
  if (isWindows) {
    inputStream = process.stdin;
  } else {
    const fs = require('fs');
    inputStream = fs.createReadStream('/dev/tty');
  }
  const rl = readline.createInterface({
    input: inputStream,
    output: process.stdout,
  });
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      if (!isWindows) {
        try { inputStream.destroy(); } catch {}
      }
      resolve(answer.trim());
    });
  });
}

function buildAgentAModelsV2() {
  const defs = {};
  for (const [slug, displayName] of Object.entries(MODEL_NAMES)) {
    defs[slug] = {
      name: displayName,
      family: 'openai',
      capabilities: { tools: true, input: ['text', 'image'], output: ['text'] },
      limit: { context: 128000, output: 4096 },
    };
  }
  return defs;
}

function buildAgentAModelsV1() {
  const defs = {};
  for (const [slug, displayName] of Object.entries(MODEL_NAMES)) {
    defs[slug] = {
      name: displayName,
      family: 'openai',
      tool_call: true,
      limit: { context: 128000, output: 4096 },
    };
  }
  return defs;
}

function generateConfig(apiKey) {
  // Native V2 shape (https://opencode.ai/v2/docs/migrate-v1/):
  // providers (plural) + package + settings.baseURL/apiKey
  // + capabilities.tools instead of tool_call.
  // Package uses the /responses runtime — Agent-A serves the OpenAI Responses API
  // (not chat/completions). Legacy `provider` block is dual-written for v1 clients.
  return {
    $schema: 'https://opencode.ai/config.json',
    providers: {
      'agent-a': {
        name: 'Agent-A',
        package: '@opencode/ai/providers/openai-compatible/responses',
        settings: {
          apiKey,
          baseURL: 'https://api.agenta.chat/v1',
        },
        models: buildAgentAModelsV2(),
      },
    },
    provider: {
      'agent-a': {
        npm: '@ai-sdk/openai-compatible',
        name: 'Agent-A',
        options: {
          apiKey,
          baseURL: 'https://api.agenta.chat/v1',
        },
        models: buildAgentAModelsV1(),
      },
    },
    model: 'agent-a/strategic-challenger',
  };
}

function findExistingConfig() {
  if (fs.existsSync(OPENCODE_CONFIG)) return OPENCODE_CONFIG;
  if (fs.existsSync(OPENCODE_CONFIGC)) return OPENCODE_CONFIGC;
  return null;
}

function backupConfig(configPath) {
  const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const backupPath = configPath + `.bak.${ts}`;
  fs.copyFileSync(configPath, backupPath);
  return backupPath;
}

function readExistingConfig(configPath) {
  try {
    let raw = fs.readFileSync(configPath, 'utf8');
    // Strip jsonc comments if .jsonc
    if (configPath.endsWith('.jsonc')) {
      raw = raw.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');
    }
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function mergeConfig(existing, newConfig) {
  const merged = { ...existing };

  // V2 canonical block: providers (plural)
  if (!merged.providers) merged.providers = {};
  if (!merged.providers['agent-a']) {
    merged.providers['agent-a'] = newConfig.providers['agent-a'];
  } else {
    const v2 = merged.providers['agent-a'];
    v2.package = newConfig.providers['agent-a'].package;
    v2.name = newConfig.providers['agent-a'].name;
    v2.settings = { ...v2.settings, ...newConfig.providers['agent-a'].settings };
    if (!v2.models) v2.models = {};
    for (const [slug, model] of Object.entries(newConfig.providers['agent-a'].models)) {
      if (!v2.models[slug]) {
        v2.models[slug] = model;
      } else {
        v2.models[slug].name = model.name;
        // Keep v2 shape healthy on re-run (v1 clients may have left tool_call behind)
        if (v2.models[slug].tool_call !== undefined) delete v2.models[slug].tool_call;
        if (!v2.models[slug].capabilities) v2.models[slug].capabilities = model.capabilities;
        if (!v2.models[slug].limit) v2.models[slug].limit = model.limit;
      }
    }
  }

  // Legacy V1 block: provider (singular) — kept so OpenCode v1 still works.
  // V2 reads the same file and normalizes this, so dual-write is safe.
  if (!merged.provider) merged.provider = {};
  if (!merged.provider['agent-a']) {
    merged.provider['agent-a'] = newConfig.provider['agent-a'];
    return merged;
  }

  const agenta = merged.provider['agent-a'];

  // Set npm + name
  agenta.npm = newConfig.provider['agent-a'].npm;
  agenta.name = newConfig.provider['agent-a'].name;

  // Set options (apiKey, baseURL)
  agenta.options = { ...agenta.options, ...newConfig.provider['agent-a'].options };

  // Merge models — add new, update name of existing
  if (!agenta.models) agenta.models = {};
  for (const [slug, model] of Object.entries(newConfig.provider['agent-a'].models)) {
    if (!agenta.models[slug]) {
      agenta.models[slug] = model;
    } else {
      // Update display name if it changed (e.g. "DeepSeek V4" → "Gemini 3.7 Flash")
      agenta.models[slug].name = model.name;
    }
  }

  return merged;
}

function writeConfig(configPath, config) {
  // Always write as .json (not .jsonc)
  const targetPath = configPath.endsWith('.jsonc')
    ? configPath.replace('.jsonc', '.json')
    : configPath;
  fs.writeFileSync(targetPath, JSON.stringify(config, null, 2) + '\n', 'utf8');
  return targetPath;
}

function hasOpenCode() {
  // Check standard PATH
  try {
    execFileSync('opencode', ['--version'], { stdio: 'ignore' });
    return true;
  } catch {
    // Linux: check ~/.local/bin/opencode
    if (process.platform === 'linux') {
      const localBin = path.join(os.homedir(), '.local', 'bin', 'opencode');
      if (fs.existsSync(localBin)) {
        try {
          execFileSync(localBin, ['--version'], { stdio: 'ignore' });
          return true;
        } catch {
          return false;
        }
      }
    }
    // Windows: check npm global bin directories
    if (process.platform === 'win32') {
      const appData = process.env.APPDATA;
      if (appData) {
        const npmBin = path.join(appData, 'npm', 'opencode.cmd');
        if (fs.existsSync(npmBin)) {
          try {
            execFileSync(npmBin, ['--version'], { stdio: 'ignore' });
            return true;
          } catch {
            return false;
          }
        }
      }
      // Also check common user npm global prefix
      const userProfile = process.env.USERPROFILE;
      if (userProfile) {
        const npmPrefix = path.join(userProfile, 'AppData', 'Roaming', 'npm', 'opencode.cmd');
        if (fs.existsSync(npmPrefix)) {
          try {
            execFileSync(npmPrefix, ['--version'], { stdio: 'ignore' });
            return true;
          } catch {
            return false;
          }
        }
      }
    }
    return false;
  }
}

function installOpenCode() {
  const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
  console.log(chalk.cyan('  OpenCode is not installed. Installing it now (v2)...'));
  // V2 package is @opencode/cli. V1 package (opencode-ai) is deprecated.
  // Try v2 first, fall back to v1 only if the registry blocks it.
  try {
    execFileSync(npm, ['install', '--global', '@opencode/cli'], { stdio: 'inherit' });
  } catch {
    console.log(chalk.yellow('  @opencode/cli install failed, trying legacy opencode-ai...'));
    execFileSync(npm, ['install', '--global', 'opencode-ai'], { stdio: 'inherit' });
  }

  // Linux: ensure binary is in PATH for non-interactive shells
  if (process.platform === 'linux') {
    const homeDir = os.homedir();
    const localBin = path.join(homeDir, '.local', 'bin');
    const opencodeBin = path.join(localBin, 'opencode');

    // Check if binary exists in ~/.local/bin
    if (fs.existsSync(opencodeBin)) {
      // Try symlink to /usr/local/bin (requires sudo)
      try {
        execSync(`sudo ln -sf ${opencodeBin} /usr/local/bin/opencode`, { stdio: 'ignore' });
        console.log(chalk.green('  ✓ Symlinked to /usr/local/bin/opencode.'));
      } catch {
        // Fallback: add to ~/.profile for non-interactive shells
        const profilePath = path.join(homeDir, '.profile');
        const pathExport = `\n# Agent-A: Add OpenCode to PATH\nexport PATH="$HOME/.local/bin:$PATH"\n`;
        if (!fs.existsSync(profilePath) || !fs.readFileSync(profilePath, 'utf8').includes('.local/bin')) {
          fs.appendFileSync(profilePath, pathExport);
          console.log(chalk.green('  ✓ Added ~/.local/bin to PATH in ~/.profile.'));
        }
      }
    }
  }
}

function testConnection(apiKey) {
  const https = require('https');
  // Agent-A serves the OpenAI Responses API (not chat/completions)
  const testData = JSON.stringify({
    model: 'frontend-designer',
    input: 'Say "hello" in one word.',
    max_output_tokens: 10,
  });

  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        hostname: 'api.agenta.chat',
        path: '/v1/responses',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${apiKey}`,
          'Content-Length': Buffer.byteLength(testData),
        },
        timeout: 15000,
      },
      (res) => {
        let body = '';
        res.on('data', (chunk) => (body += chunk));
        res.on('end', () => {
          let parsed = body;
          try { parsed = JSON.parse(body); } catch {}
          resolve({ status: res.statusCode, body: parsed });
        });
      }
    );
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    req.write(testData);
    req.end();
  });
}

// ── Commands ────────────────────────────────────────────────
async function cmdInit(apiKeyArg, yesFlag = false) {
  console.log('');
  console.log(chalk.bold('  Agent-A \u2014 Your AI Founding Team\n'));

  console.log('  Five specialized AI teammates for OpenCode:');
  console.log('');
  for (const [slug] of Object.entries(MODEL_NAMES)) {
    const icon = ROLE_ICONS[slug];
    const label = ROLE_LABELS[slug];
    console.log(`    ${icon}  ${label}`);
  }
  console.log('');

  // Get API key from flag or prompt
  let apiKey = apiKeyArg;
  if (!apiKey) {
    console.log(chalk.cyan('  ┌─────────────────────────────────────────────────────────┐'));
    console.log(chalk.cyan('  │  Need an API key? Get one free at:                     │'));
    console.log(chalk.cyan('  │  https://agenta.chat/setup                             │'));
    console.log(chalk.cyan('  │                                                        │'));
    console.log(chalk.cyan('  │  1. Visit the URL above                                │'));
    console.log(chalk.cyan('  │  2. Sign in with your email                            │'));
    console.log(chalk.cyan('  │  3. Copy your API key (starts with ak_)                │'));
    console.log(chalk.cyan('  └─────────────────────────────────────────────────────────┘'));
    console.log('');
    apiKey = await prompt(chalk.cyan('  Paste your API key: '));
  }
  if (!apiKey) {
    console.log(chalk.red('  No key provided. You can get a free API key at:'));
    console.log(chalk.red('  https://agenta.chat/setup'));
    process.exit(1);
  }

  // Validate key format
  if (!apiKey.startsWith('ak_')) {
    console.log(chalk.yellow('  Warning: Key doesn\'t start with "ak_". Double-check your API key.'));
    console.log(chalk.yellow('  Get a valid key at: https://agenta.chat/setup'));
  }

  console.log('');

  if (!hasOpenCode()) {
    try {
      installOpenCode();
      console.log(chalk.green('  ✓ OpenCode installed.'));
    } catch (err) {
      console.log(chalk.red(`  Could not install OpenCode: ${err.message}`));
      console.log('  Install it manually with: npm install --global @opencode/cli');
      process.exit(1);
    }
  } else {
    console.log(chalk.green('  ✓ OpenCode is installed.'));
  }

  // Find or create OpenCode config
  let configPath = findExistingConfig();
  let existingConfig = null;

  if (configPath) {
    console.log(chalk.cyan(`  Found existing config at ${configPath}`));
    existingConfig = readExistingConfig(configPath);

    if (existingConfig && (existingConfig.providers?.['agent-a'] || existingConfig.provider?.['agent-a'])) {
      console.log(chalk.yellow('  Agent-A provider already configured.'));
      let overwrite;
      if (yesFlag) {
        overwrite = 'y';
        console.log(chalk.cyan('  --yes flag set, updating models.'));
      } else {
        overwrite = await prompt(chalk.cyan('  Update Agent-A models? (y/N): '));
      }
      if (overwrite.toLowerCase() !== 'y' && overwrite.toLowerCase() !== 'yes') {
        console.log('  Keeping existing configuration. Done.');
        process.exit(0);
      }
    }

    // Backup
    const backupPath = backupConfig(configPath);
    console.log(chalk.cyan(`  Backed up to ${backupPath}`));
  } else {
    // Create directory and config
    fs.mkdirSync(OPENCODE_DIR, { recursive: true });
    configPath = OPENCODE_CONFIG;
    console.log(chalk.cyan(`  Creating ${configPath}`));
  }

  // Generate and merge config
  const newConfig = generateConfig(apiKey);

  let finalConfig;
  if (existingConfig) {
    finalConfig = mergeConfig(existingConfig, newConfig);
    console.log(chalk.cyan('  Merged Agent-A provider into existing config.'));
  } else {
    finalConfig = newConfig;
  }

  // Write config
  const writtenPath = writeConfig(configPath, finalConfig);
  console.log(chalk.green(`  Wrote ${writtenPath}`));

  // Test connection
  console.log('');
  console.log(chalk.cyan('  Testing connection...'));
  try {
    const result = await testConnection(apiKey);
    if (result.status === 200 && (result.body?.output || result.body?.choices)) {
      console.log(chalk.green('  ✓ Connection successful.'));
    } else if (result.status === 401 || result.status === 403) {
      console.log(chalk.yellow('  ⚠ Auth failed. Check your API key. Config was still written.'));
    } else {
      const detail = typeof result.body === 'string'
        ? result.body.slice(0, 200)
        : result.body?.error?.message || JSON.stringify(result.body).slice(0, 200);
      console.log(chalk.yellow(`  ⚠ API response ${result.status}: ${detail}`));
      console.log(chalk.dim('  Config was still written.'));
    }
  } catch (err) {
    console.log(chalk.yellow(`  ⚠ Connection test failed: ${err.message}. Config was still written.`));
  }

  console.log('');
  console.log(chalk.bold.green('  \u2713 Done! Your AI founding team is installed.\n'));

  console.log('  Team:');
  for (const slug of Object.keys(MODEL_NAMES)) {
    const icon = ROLE_ICONS[slug];
    const label = ROLE_LABELS[slug];
    console.log(`    ${icon}  ${label} \u2014 agent-a/${slug}`);
  }
  console.log('');
  console.log('  HOW TO USE YOUR TEAM:');
  console.log('');
  console.log('  Option A: OpenCode (local)');
  console.log('    1. Type opencode in your terminal');
  console.log('    2. Type /model to see available models');
  console.log('    3. Select an Agent-A model (e.g. agent-a/strategic-challenger)');
  console.log('    4. Start chatting — the agent is ready');
  console.log('');
  console.log('  Option B: Hermes (remote — run from any device)');
  console.log('    1. Go to https://agenta.chat/setremoteteam');
  console.log('    2. Add the Agent-A provider with your API key');
  console.log('    3. Select any team member and start chatting');
  console.log('');
  console.log('  Your API key is in your config. To see it:');
  console.log('    cat ~/.config/opencode/opencode.json | grep apiKey');
  console.log('');
  console.log(chalk.dim('  Tip: Run "npx @agent-a/cli test" to verify your connection later'));
  console.log('');
}

async function cmdTest() {
  console.log('');
  console.log(chalk.bold('  Agent-A \u2014 Connection Test\n'));

  // Find config
  const configPath = findExistingConfig();
  if (!configPath) {
    console.log(chalk.red('  No OpenCode config found.'));
    console.log('  Run: npx @agent-a/cli init');
    process.exit(1);
  }

  const config = readExistingConfig(configPath);
  const v2 = config?.providers?.['agent-a'];
  const v1 = config?.provider?.['agent-a'];
  if (!config || (!v2 && !v1)) {
    console.log(chalk.red('  Agent-A not configured in OpenCode.'));
    console.log('  Run: npx @agent-a/cli init');
    process.exit(1);
  }

  const apiKey = v2?.settings?.apiKey || v1?.options?.apiKey;
  if (!apiKey) {
    console.log(chalk.red('  No API key found in config.'));
    process.exit(1);
  }

  console.log(chalk.cyan('  Testing connection to api.agenta.chat...'));
  console.log('');

  try {
    const result = await testConnection(apiKey);

    if (result.status === 200 && (result.body?.output || result.body?.choices)) {
      console.log(chalk.green('  \u2713 Connection successful!'));
      console.log('');
      const reply = result.body?.output?.[0]?.content?.[0]?.text
        || result.body?.output_text
        || result.body?.choices?.[0]?.message?.content
        || '(no response)';
      console.log(chalk.dim(`  Model response: ${reply}`));
      console.log('');
      console.log('  All five models are ready:');
      for (const slug of Object.keys(MODEL_NAMES)) {
        console.log(`    \u2022 agent-a/${slug}`);
      }
    } else if (result.status === 401 || result.status === 403) {
      console.log(chalk.red('  \u2717 Authentication failed. Check your API key.'));
    } else {
      console.log(chalk.yellow(`  \u26A0 Unexpected response (${result.status})`));
      if (typeof result.body === 'string') {
        console.log(chalk.dim(`  ${result.body.slice(0, 200)}`));
      }
    }
  } catch (err) {
    console.log(chalk.red(`  \u2717 Connection failed: ${err.message}`));
    console.log('  Check your internet connection and try again.');
  }

  console.log('');
}

async function cmdModels() {
  console.log('');
  console.log(chalk.bold('  Agent-A \u2014 Your AI Founding Team\n'));

  const configPath = findExistingConfig();
  const cfg = configPath && readExistingConfig(configPath);
  const configured = !!(
    cfg && (cfg.providers?.['agent-a'] || cfg.provider?.['agent-a'])
  );

  const status = configured ? chalk.green('installed') : chalk.yellow('not installed');

  for (const [slug, label] of Object.entries(ROLE_LABELS)) {
    const icon = ROLE_ICONS[slug];
    const name = MODEL_NAMES[slug];
    console.log(`  ${icon}  ${label}`);
    console.log(`      agent-a/${slug}`);
    console.log(chalk.dim(`      ${name} \u2014 ${status}`));
    console.log('');
  }
}

async function cmdHelp() {
  console.log('');
  console.log(chalk.bold('  Agent-A CLI \u2014 Your AI Founding Team\n'));
  console.log('  Commands:');
  console.log('');
  console.log('    init    Install your AI founding team in OpenCode');
  console.log('    test    Test your Agent-A API connection');
  console.log('    models  List available Agent-A roles');
  console.log('    help    Show this help message');
  console.log('');
  console.log('  Usage:');
  console.log('');
  console.log('    npx @agent-a/cli init     # Install your team');
  console.log('    npx @agent-a/cli test     # Test connection');
  console.log('    npx @agent-a/cli models   # List all models');
  console.log('');
  console.log('  Your AI Founding Team:');
  console.log('');
  console.log('    \u25A0  Strategic Challenger \u2014 Strategy, challenge, focus');
  console.log('    \u25B6  Frontend Designer \u2014 UI components, layouts, styling');
  console.log('    \u25C6  Backend Hacker \u2014 APIs, databases, server logic');
  console.log('    \u25CF  Market Operator \u2014 problem, positioning, distribution');
  console.log('');
  console.log(chalk.bold('  GET YOUR API KEY:'));
  console.log('');
  console.log('    1. Go to https://agenta.chat/setup');
  console.log('    2. Sign in with your email');
  console.log('    3. Copy your API key (starts with ak_)');
  console.log('');
  console.log('  HOW TO USE:');
  console.log('');
  console.log('  OpenCode (local):');
  console.log('    1. Type opencode in your terminal');
  console.log('    2. Type /model to see available models');
  console.log('    3. Select an Agent-A model (e.g. agent-a/strategic-challenger)');
  console.log('    4. Start chatting');
  console.log('');
  console.log('  Hermes (remote):');
  console.log('    1. Go to https://agenta.chat/setremoteteam');
  console.log('    2. Add the Agent-A provider with your API key');
  console.log('    3. Select any team member and start chatting');
  console.log('');
}

// ── Main ────────────────────────────────────────────────────
async function main() {
  const args = process.argv.slice(2);

  // Parse --api-key and --yes flags
  let apiKeyFlag = null;
  let yesFlag = false;
  const filteredArgs = [];
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--api-key' && args[i + 1]) {
      apiKeyFlag = args[i + 1];
      i++;
    } else if (args[i] === '--yes' || args[i] === '-y') {
      yesFlag = true;
    } else {
      filteredArgs.push(args[i]);
    }
  }

  const cmd = filteredArgs[0] || 'help';

  switch (cmd) {
    case 'init':
      await cmdInit(apiKeyFlag, yesFlag);
      break;
    case 'test':
      await cmdTest();
      break;
    case 'models':
      await cmdModels();
      break;
    case 'help':
    case '--help':
    case '-h':
      await cmdHelp();
      break;
    default:
      console.log(chalk.red(`  Unknown command: ${cmd}\n`));
      await cmdHelp();
      process.exit(1);
  }
}

main().catch((err) => {
  console.error(chalk.red(`  Error: ${err.message}`));
  process.exit(1);
});
